from paging import page_items

def test_page_two():
    assert page_items(list(range(10)), 2, 3) == [3, 4, 5]

def test_last_partial():
    assert page_items(list(range(7)), 3, 3) == [6]

def test_beyond():
    assert page_items(list(range(5)), 5, 2) == []

def test_bad_args():
